/**
 * Data shapes the components receive from the backend (generated by scripts/export-ui/export-ui.mjs).
 * Dates arrive as ISO strings over JSON; parse them if your API doesn't.
 */
import type { ChatCard } from "@/lib/ai/types";
import type { Urgency } from "@/types/domain";

/** From lib/services/conversations.ts */
export interface Message {
  id: string;
  conversation_id: string;
  profile_id: string | null;
  role: "user" | "assistant" | "doctor" | "system";
  content: string;
  cards: ChatCard[];
  urgency: Urgency | null;
  answer_id: string | null;
  created_at: Date;
}

/** From lib/services/health-record.ts */
export interface Condition {
  id: string;
  profile_id: string;
  name: string;
  status: string;
  diagnosed_on: string | null;
  notes: string | null;
  source: string;
}

/** From lib/services/health-record.ts */
export interface Allergy {
  id: string;
  profile_id: string;
  substance: string;
  reaction: string | null;
  severity: string | null;
}

/** From lib/services/reports.ts */
export interface ReportFolder {
  id: string;
  family_id: string;
  name: string;
  icon: string;
  is_default: boolean;
  report_count?: number;
}

/** From lib/services/reports.ts */
export interface ReportRow {
  id: string;
  family_id: string;
  profile_id: string;
  profile_name: string;
  folder_id: string | null;
  folder_name: string | null;
  title: string;
  document_type: string;
  report_date: string | null;
  doctor_name: string | null;
  lab_name: string | null;
  status: string;
  quality: { score: number; readable: boolean; issues: string[] } | null;
  summary: string | null;
  extraction: { provider?: string; isMock?: boolean; documentType?: { type: string; confidence: number }; reportDate?: { value: string | null; confidence: number }; enhancement?: string[]; errors?: string[] } | null;
  provider: string | null;
  doctor_reviewed_at: Date | null;
  doctor_notes: string | null;
  created_at: Date;
  has_thumbnail?: boolean;
}
